INSERT INTO coding_round_questions (question_title, question_description) VALUES
('Two Sum', 'Given an array of integers nums and an integer target, return the indices of the two numbers such that they add up to target. You may assume that each input has exactly one solution, and you may not use the same element twice. Return the answer in any order.'),
('Best Time to Buy and Sell Stock', 'You are given an array prices where prices[i] is the price of a given stock on day i. You want to maximize your profit by choosing a single day to buy one stock and a different day in the future to sell it. Return the maximum profit you can achieve; return 0 if no profit is possible.'),
('Contains Duplicate', 'Given an integer array nums, return true if any value appears at least twice in the array, and return false if every element is distinct.'),
('Product of Array Except Self', 'Given an integer array nums, return an array answer such that answer[i] is equal to the product of all the elements of nums except nums[i]. You must write an algorithm that runs in O(n) time without using the division operation.'),
('Maximum Subarray', 'Given an integer array nums, find the contiguous subarray (containing at least one number) which has the largest sum, and return its sum.'),
('Maximum Product Subarray', 'Given an integer array nums, find a contiguous non-empty subarray within the array that has the largest product, and return the product.'),
('Find Minimum in Rotated Sorted Array', 'Suppose an array of length n sorted in ascending order is rotated between 1 and n times. Given the sorted rotated array nums of unique elements, return the minimum element of this array. You must write an algorithm that runs in O(log n) time.'),
('Search in Rotated Sorted Array', 'There is an integer array nums sorted in ascending order with distinct values, which is possibly rotated at an unknown pivot. Given the array and an integer target, return the index of target if it is in nums, or -1 if it is not, in O(log n) time.'),
('3Sum', 'Given an integer array nums, return all the triplets [nums[i], nums[j], nums[k]] such that i != j, i != k, and j != k, and nums[i] + nums[j] + nums[k] == 0. The solution set must not contain duplicate triplets.'),
('Container With Most Water', 'Given n non-negative integers height where each represents a point at coordinate (i, height[i]), find two lines that together with the x-axis form a container that holds the most water, and return the maximum amount of water it can store.'),
('Climbing Stairs', 'You are climbing a staircase that takes n steps to reach the top. Each time you can either climb 1 or 2 steps. In how many distinct ways can you climb to the top?'),
('Coin Change', 'You are given an integer array coins representing coins of different denominations and an integer amount representing a total amount of money. Return the fewest number of coins needed to make up that amount; if the amount cannot be made up, return -1.'),
('Longest Increasing Subsequence', 'Given an integer array nums, return the length of the longest strictly increasing subsequence.'),
('Longest Common Subsequence', 'Given two strings text1 and text2, return the length of their longest common subsequence. If there is no common subsequence, return 0.'),
('Word Break', 'Given a string s and a dictionary of strings wordDict, return true if s can be segmented into a space-separated sequence of one or more dictionary words.'),
('Combination Sum', 'Given an array of distinct integers candidates and a target integer target, return a list of all unique combinations of candidates where the chosen numbers sum to target. The same number may be chosen from candidates an unlimited number of times.'),
('House Robber', 'You are a professional robber planning to rob houses along a street, each with a certain amount of money. Adjacent houses have connected security systems, so you cannot rob two adjacent houses on the same night. Return the maximum amount of money you can rob without alerting the police.'),
('House Robber II', 'This is the same as House Robber, except now all houses are arranged in a circle, meaning the first and last house are adjacent to each other. Return the maximum amount of money you can rob without robbing two adjacent houses.'),
('Decode Ways', 'A message containing letters A-Z is encoded using the mapping ''A'' -> ''1'', ''B'' -> ''2'', ..., ''Z'' -> ''26''. Given a string s containing only digits, return the number of ways to decode it.'),
('Unique Paths', 'There is a robot on an m x n grid. The robot is initially located at the top-left corner and can only move either down or right at any point. Return the number of possible unique paths that the robot can take to reach the bottom-right corner.'),
('Jump Game', 'You are given an integer array nums. You are initially positioned at the array''s first index, and each element represents your maximum jump length at that position. Return true if you can reach the last index, or false otherwise.'),
('Jump Game II', 'Given an array of non-negative integers nums, you are initially at the first index. Each element represents your maximum jump length. Return the minimum number of jumps required to reach the last index.'),
('Merge Intervals', 'Given an array of intervals where intervals[i] = [starti, endi], merge all overlapping intervals and return an array of the non-overlapping intervals that cover all the intervals in the input.'),
('Insert Interval', 'You are given an array of non-overlapping intervals sorted by start time, and a new interval to insert. Insert the new interval into the intervals, merging as necessary, and return the resulting array of intervals sorted by start time.'),
('Non-overlapping Intervals', 'Given an array of intervals, return the minimum number of intervals you need to remove to make the rest of the intervals non-overlapping.'),
('Meeting Rooms II', 'Given an array of meeting time intervals where intervals[i] = [starti, endi], return the minimum number of conference rooms required to hold all the meetings.'),
('Valid Parentheses', 'Given a string s containing just the characters ''('', '')'', ''{'', ''}'', ''['' and '']'', determine if the input string is valid, meaning every opening bracket has a matching closing bracket of the same type in the correct order.'),
('Generate Parentheses', 'Given n pairs of parentheses, write a function to generate all combinations of well-formed parentheses.'),
('Valid Anagram', 'Given two strings s and t, return true if t is an anagram of s, meaning it uses exactly the same letters with the same frequencies, and false otherwise.'),
('Group Anagrams', 'Given an array of strings strs, group the anagrams together. You can return the answer in any order.'),
('Longest Substring Without Repeating Characters', 'Given a string s, find the length of the longest substring without repeating characters.'),
('Longest Repeating Character Replacement', 'Given a string s and an integer k, you can choose any character and change it to any other uppercase letter, at most k times. Return the length of the longest substring containing the same letter you can get after performing this operation.'),
('Minimum Window Substring', 'Given two strings s and t, return the minimum window substring of s such that every character in t (including duplicates) is included in the window. If there is no such substring, return the empty string.'),
('Palindromic Substrings', 'Given a string s, return the number of palindromic substrings in it. A substring is a contiguous sequence of characters within the string.'),
('Longest Palindromic Substring', 'Given a string s, return the longest palindromic substring in s.'),
('Valid Palindrome', 'Given a string s, after converting all uppercase letters into lowercase letters and removing all non-alphanumeric characters, determine if it reads the same forward and backward.'),
('Encode and Decode Strings', 'Design an algorithm to encode a list of strings to a single string, and a corresponding decode function that can reconstruct the original list of strings from the encoded string, without relying on any delimiter characters that might appear in the strings.'),
('Top K Frequent Elements', 'Given an integer array nums and an integer k, return the k most frequent elements. You may return the answer in any order.'),
('Sort Colors', 'Given an array nums with n objects colored red, white, or blue, represented by the integers 0, 1, and 2, sort them in-place so that objects of the same color are adjacent, using the colors in the order red, white and blue.'),
('Kth Largest Element in an Array', 'Given an integer array nums and an integer k, return the kth largest element in the array. Note that it is the kth largest element in sorted order, not the kth distinct element.'),
('Task Scheduler', 'Given a characters array tasks representing CPU tasks and a non-negative integer n representing the cooldown period between two same tasks, return the least number of units of time the CPU will take to finish all the given tasks.'),
('Reverse Linked List', 'Given the head of a singly linked list, reverse the list and return the reversed list''s head.'),
('Merge Two Sorted Lists', 'You are given the heads of two sorted linked lists. Merge the two lists into one sorted list by splicing together the nodes of the first two lists, and return the head of the merged linked list.'),
('Reorder List', 'You are given the head of a singly linked list. Reorder the list to be in the form L0 -> Ln -> L1 -> Ln-1 -> L2 -> Ln-2 -> ... You may not modify the values in the list''s nodes, only the nodes themselves may be changed.'),
('Remove Nth Node From End of List', 'Given the head of a linked list, remove the nth node from the end of the list and return its head.'),
('Linked List Cycle', 'Given the head of a linked list, determine if the linked list has a cycle in it, meaning some node can be reached again by continuously following the next pointer.'),
('Merge k Sorted Lists', 'You are given an array of k linked-lists lists, each linked-list is sorted in ascending order. Merge all the linked-lists into one sorted linked-list and return it.'),
('Add Two Numbers', 'You are given two non-empty linked lists representing two non-negative integers where the digits are stored in reverse order. Add the two numbers and return the sum as a linked list in the same reverse-order format.'),
('LRU Cache', 'Design a data structure that follows the constraints of a Least Recently Used (LRU) cache, implementing get and put operations both in O(1) average time complexity.'),
('Copy List with Random Pointer', 'A linked list of length n is given such that each node contains an additional random pointer which could point to any node in the list, or null. Construct a deep copy of the list and return the head of the copied linked list.'),
('Invert Binary Tree', 'Given the root of a binary tree, invert the tree by swapping the left and right children of every node, and return its root.'),
('Maximum Depth of Binary Tree', 'Given the root of a binary tree, return its maximum depth, defined as the number of nodes along the longest path from the root node down to the farthest leaf node.'),
('Diameter of Binary Tree', 'Given the root of a binary tree, return the length of the diameter of the tree, defined as the length of the longest path between any two nodes, which may or may not pass through the root.'),
('Balanced Binary Tree', 'Given a binary tree, determine if it is height-balanced, meaning the left and right subtrees of every node differ in height by no more than 1.'),
('Same Tree', 'Given the roots of two binary trees p and q, write a function to check if they are the same, meaning structurally identical with the same node values.'),
('Subtree of Another Tree', 'Given the roots of two binary trees root and subRoot, return true if there is a subtree of root with the same structure and node values as subRoot, or false otherwise.'),
('Lowest Common Ancestor of a Binary Search Tree', 'Given a binary search tree and two nodes p and q, find the lowest common ancestor node of the two given nodes, defined as the lowest node that has both p and q as descendants.'),
('Binary Tree Level Order Traversal', 'Given the root of a binary tree, return the level order traversal of its nodes'' values, meaning left to right, level by level, as a list of lists.'),
('Binary Tree Right Side View', 'Given the root of a binary tree, imagine yourself standing on the right side of it, and return the values of the nodes you can see ordered from top to bottom.'),
('Count Good Nodes in Binary Tree', 'Given a binary tree root, a node X in the tree is named good if in the path from root to X there are no nodes with a value greater than X''s value. Return the number of good nodes in the binary tree.'),
('Validate Binary Search Tree', 'Given the root of a binary tree, determine if it is a valid binary search tree, meaning for every node its left subtree values are strictly less and its right subtree values are strictly greater.'),
('Kth Smallest Element in a BST', 'Given the root of a binary search tree and an integer k, return the kth smallest value among all the values of the nodes in the tree.'),
('Construct Binary Tree from Preorder and Inorder Traversal', 'Given two integer arrays preorder and inorder representing the preorder and inorder traversal of a binary tree, construct and return the binary tree.'),
('Binary Tree Maximum Path Sum', 'Given the root of a binary tree, return the maximum path sum of any non-empty path, where a path is a sequence of nodes connected by edges and each node may appear at most once.'),
('Serialize and Deserialize Binary Tree', 'Design an algorithm to serialize a binary tree into a string, and to deserialize that string back into the original binary tree structure.'),
('Implement Trie (Prefix Tree)', 'Implement a trie with insert, search, and startsWith methods, supporting efficient storage and retrieval of keys from a dataset of strings.'),
('Design Add and Search Words Data Structure', 'Design a data structure that supports adding new words and finding if a string matches any previously added string, where the search string may contain the wildcard character ''.'' that matches any single letter.'),
('Word Search II', 'Given an m x n board of characters and a list of strings words, return all words on the board, where each word must be constructed from letters of sequentially adjacent cells and the same cell may not be used more than once in a word.'),
('Number of Islands', 'Given an m x n 2D binary grid which represents a map of ''1''s (land) and ''0''s (water), return the number of islands, where an island is surrounded by water and is formed by connecting adjacent lands horizontally or vertically.'),
('Clone Graph', 'Given a reference of a node in a connected undirected graph, return a deep copy (clone) of the graph, where each node contains a value and a list of its neighbors.'),
('Max Area of Island', 'Given an m x n binary matrix grid, return the maximum area of an island in grid, where an island is a group of 1''s connected 4-directionally and the area is the number of cells in it.'),
('Pacific Atlantic Water Flow', 'Given an m x n matrix of heights representing the height of each cell above sea level, return a list of coordinates where water can flow to both the Pacific and Atlantic oceans.'),
('Surrounded Regions', 'Given an m x n matrix board containing ''X'' and ''O'', capture all regions that are 4-directionally surrounded by ''X'' by flipping all ''O''s into ''X''s in that surrounded region.'),
('Rotting Oranges', 'You are given an m x n grid where each cell can have a value of 0 (empty), 1 (fresh orange), or 2 (rotten orange). Every minute, any fresh orange adjacent to a rotten orange becomes rotten. Return the minimum number of minutes until no cell has a fresh orange, or -1 if impossible.'),
('Walls and Gates', 'You are given an m x n grid rooms initialized with values representing walls, gates, or empty rooms. Fill each empty room with the distance to its nearest gate, leaving it as infinity if it is unreachable.'),
('Course Schedule', 'There are numCourses courses labeled from 0 to numCourses - 1, and prerequisites where prerequisites[i] = [ai, bi] indicates you must take course bi first. Return true if you can finish all courses, given the prerequisites.'),
('Course Schedule II', 'Given the total number of courses and a list of prerequisite pairs, return the ordering of courses you should take to finish all courses; return an empty array if it is impossible to finish all courses.'),
('Graph Valid Tree', 'Given n nodes labeled from 0 to n-1 and a list of undirected edges, write a function to check whether these edges make up a valid tree, meaning the graph is fully connected and contains no cycles.'),
('Number of Connected Components in an Undirected Graph', 'You have a graph of n nodes labeled 0 to n-1, given an array of undirected edges where edges[i] = [ai, bi] indicates an edge between ai and bi. Return the number of connected components in the graph.'),
('Redundant Connection', 'In this problem, a tree is an undirected graph that is connected and has no cycles. You are given a graph that started as a tree with n nodes but had one additional edge added, creating a cycle. Return the edge that can be removed so that the resulting graph is a tree of n nodes.'),
('Word Ladder', 'Given two words beginWord and endWord, and a dictionary wordList, return the number of words in the shortest transformation sequence from beginWord to endWord, changing only one letter at a time and each transformed word must exist in wordList.'),
('Alien Dictionary', 'There is a new alien language that uses the English alphabet, but the order among the letters is unknown to you. You are given a list of strings words sorted lexicographically by the rules of this new language. Derive the order of letters in this language.'),
('Network Delay Time', 'You are given a network of n nodes labeled from 1 to n, and times representing directed edges with travel times. Given a starting node k, return the minimum time it takes for all n nodes to receive a signal sent from node k, or -1 if impossible.'),
('Cheapest Flights Within K Stops', 'There are n cities connected by flights, given as edges with prices. Given a source, destination, and k, return the cheapest price to travel from source to destination with at most k stops, or -1 if there is no such route.'),
('Min Cost to Connect All Points', 'You are given an array points representing integer coordinates of points on a 2D plane, where the cost of connecting two points is their Manhattan distance. Return the minimum cost to make all points connected.'),
('Set Matrix Zeroes', 'Given an m x n integer matrix, if an element is 0, set its entire row and column to 0, and do it in place.'),
('Spiral Matrix', 'Given an m x n matrix, return all elements of the matrix in spiral order, starting from the top-left corner and moving clockwise inward.'),
('Rotate Image', 'You are given an n x n 2D matrix representing an image. Rotate the image by 90 degrees clockwise, and you must do this in place without allocating another matrix.'),
('Word Search', 'Given an m x n grid of characters board and a string word, return true if word exists in the grid, where the word can be constructed from letters of sequentially adjacent cells.'),
('Valid Sudoku', 'Determine if a 9 x 9 Sudoku board is valid, meaning each row, column, and each of the nine 3x3 sub-boxes must contain the digits 1-9 without repetition, based only on the filled cells.'),
('Permutations', 'Given an array nums of distinct integers, return all the possible permutations, in any order.'),
('Subsets', 'Given an integer array nums of unique elements, return all possible subsets, meaning the power set. The solution set must not contain duplicate subsets.'),
('Subsets II', 'Given an integer array nums that may contain duplicates, return all possible subsets, meaning the power set, without duplicate subsets in the result.'),
('Permutations II', 'Given a collection of numbers nums that might contain duplicates, return all possible unique permutations in any order.'),
('Combination Sum II', 'Given a collection of candidate numbers candidates and a target number target, find all unique combinations where the candidate numbers sum to target, where each number may only be used once in the combination.'),
('Palindrome Partitioning', 'Given a string s, partition s such that every substring of the partition is a palindrome, and return all possible palindrome partitioning of s.'),
('Letter Combinations of a Phone Number', 'Given a string containing digits from 2-9, return all possible letter combinations that the number could represent according to the standard telephone keypad mapping.'),
('N-Queens', 'The n-queens puzzle is the problem of placing n queens on an n x n chessboard such that no two queens attack each other. Given an integer n, return all distinct solutions to the n-queens puzzle.'),
('Sudoku Solver', 'Write a program to solve a Sudoku puzzle by filling the empty cells such that each row, column, and 3x3 sub-box contains all the digits 1-9 exactly once.'),
('Find Median from Data Stream', 'Design a data structure that supports adding integers from a stream one at a time and finding the median of all elements so far, at any point in time.'),
('Top K Frequent Words', 'Given an array of strings words and an integer k, return the k most frequent strings, sorted by frequency from highest to lowest, and by lexicographical order when frequencies are equal.'),
('K Closest Points to Origin', 'Given an array of points where points[i] = [xi, yi] represents a point on the X-Y plane and an integer k, return the k closest points to the origin (0, 0).'),
('Kth Largest Element in a Stream', 'Design a class to find the kth largest element in a stream, supporting a constructor that initializes the object with the integer k and an array of integers, and an add method that returns the current kth largest element after adding a new value.'),
('Last Stone Weight', 'You are given an array of integers stones where stones[i] is the weight of the ith stone. Repeatedly smash the two heaviest stones together until at most one stone remains, and return the weight of the last remaining stone, or 0 if none remain.'),
('Task Scheduling with Cooldown', 'Given a list of build tasks each with a duration and a cooldown period during which the same task cannot be run again, determine the minimum total time required to complete all tasks at least once respecting cooldowns.'),
('Design Twitter', 'Design a simplified version of Twitter where users can post tweets, follow and unfollow another user, and see the 10 most recent tweet IDs in the user''s news feed.'),
('Min Stack', 'Design a stack that supports push, pop, top, and retrieving the minimum element in constant time for all operations.'),
('Evaluate Reverse Polish Notation', 'Evaluate the value of an arithmetic expression given in Reverse Polish Notation, where valid operators are ''+'', ''-'', ''*'', and ''/'', and each operand may be an integer or another expression.'),
('Daily Temperatures', 'Given an array of integers temperatures representing daily temperatures, return an array answer such that answer[i] is the number of days you have to wait after the ith day to get a warmer temperature, or 0 if there is none.'),
('Car Fleet', 'There are n cars going to the same destination along a one-lane road, given their positions and speeds. A car fleet is a group of cars driving at the same position and same speed. Return the number of car fleets that will arrive at the destination.'),
('Largest Rectangle in Histogram', 'Given an array of integers heights representing the histogram''s bar height where the width of each bar is 1, return the area of the largest rectangle in the histogram.'),
('Basic Calculator', 'Given a string s representing a valid mathematical expression, implement a basic calculator to evaluate it, supporting non-negative integers, ''+'', ''-'', parentheses, and spaces.'),
('Sliding Window Maximum', 'You are given an array of integers nums and a sliding window of size k which moves from the very left to the very right of the array. Return an array of the maximum value in each window.'),
('Find All Anagrams in a String', 'Given two strings s and p, return an array of all the start indices of p''s anagrams in s, where an anagram is a permutation of the string.'),
('Permutation in String', 'Given two strings s1 and s2, return true if s2 contains a permutation of s1, meaning one of s1''s permutations is a substring of s2.'),
('Two Sum II - Input Array Is Sorted', 'Given a 1-indexed array of integers numbers that is already sorted in non-decreasing order, find two numbers such that they add up to a specific target number, and return the indices of the two numbers, added by one.'),
('3Sum Closest', 'Given an integer array nums of length n and an integer target, find three integers in nums such that the sum is closest to target, and return that sum.'),
('4Sum', 'Given an array nums of n integers and an integer target, return an array of all unique quadruplets [nums[a], nums[b], nums[c], nums[d]] such that they sum up to target.'),
('Trapping Rain Water', 'Given n non-negative integers representing an elevation map where the width of each bar is 1, compute how much water it can trap after raining.'),
('Rotate Array', 'Given an integer array nums, rotate the array to the right by k steps, where k is non-negative, and do it in place if possible.'),
('Missing Number', 'Given an array nums containing n distinct numbers in the range [0, n], return the only number in the range that is missing from the array.'),
('Find All Numbers Disappeared in an Array', 'Given an array nums of n integers where nums[i] is in the range [1, n], return an array of all the integers in the range [1, n] that do not appear in nums.'),
('Single Number', 'Given a non-empty array of integers nums, every element appears twice except for one. Find that single one, using an algorithm with linear runtime complexity and no extra memory.'),
('Single Number II', 'Given an integer array nums where every element appears three times except for one, which appears exactly once, find and return that single element.'),
('Number of 1 Bits', 'Write a function that takes an unsigned integer and returns the number of ''1'' bits it has, also known as the Hamming weight.'),
('Counting Bits', 'Given an integer n, return an array ans of length n + 1 such that for each i, ans[i] is the number of 1''s in the binary representation of i.'),
('Reverse Bits', 'Reverse the bits of a given 32 bits unsigned integer.'),
('Sum of Two Integers', 'Given two integers a and b, return the sum of the two integers without using the operators + and -.'),
('Missing Ranges', 'Given a sorted unique integer array nums and two integers lower and upper, return the smallest sorted list of ranges that cover every missing number in the inclusive range [lower, upper].'),
('Pow(x, n)', 'Implement a function that calculates x raised to the power n, meaning pow(x, n), handling both positive and negative integer exponents efficiently.'),
('Sqrt(x)', 'Given a non-negative integer x, return the square root of x rounded down to the nearest integer, without using any built-in exponent function or operator.'),
('Divide Two Integers', 'Given two integers dividend and divisor, divide two integers without using multiplication, division, and mod operator, returning the quotient after truncating toward zero.'),
('Multiply Strings', 'Given two non-negative integers num1 and num2 represented as strings, return the product of num1 and num2, also represented as a string, without using any built-in big integer library.'),
('Integer to Roman', 'Given an integer, convert it to a roman numeral, following the standard rules for symbols I, V, X, L, C, D and M.'),
('Roman to Integer', 'Given a roman numeral string, convert it to an integer, following the standard rules for symbols I, V, X, L, C, D and M.'),
('Fraction to Recurring Decimal', 'Given two integers representing the numerator and denominator of a fraction, return the fraction in string format; if the fractional part is repeating, enclose the repeating part in parentheses.'),
('Gas Station', 'There are n gas stations along a circular route, where gas[i] is the amount of gas at station i and cost[i] is the cost to travel from station i to station i+1. Return the starting gas station''s index if you can travel around the circuit once, otherwise return -1.'),
('Partition Labels', 'You are given a string s. Partition the string into as many parts as possible so that each letter appears in at most one part, and return a list of integers representing the size of these parts.'),
('Valid Parenthesis String', 'Given a string s containing only three characters ''('', '')'' and ''*'', where ''*'' could be treated as a single left parenthesis, a single right parenthesis, or an empty string, return true if s is valid.'),
('Minimum Number of Arrows to Burst Balloons', 'There are spherical balloons represented as intervals on the x-axis. An arrow shot at position x bursts all balloons whose interval includes x. Return the minimum number of arrows required to burst all balloons.'),
('Reconstruct Itinerary', 'Given a list of airline tickets represented as pairs of departure and arrival airports, reconstruct the itinerary in order, starting from ''JFK'', that uses all the tickets exactly once; if multiple valid itineraries exist, return the one with the smallest lexical order.'),
('Find the Duplicate Number', 'Given an array of integers nums containing n + 1 integers where each integer is in the range [1, n] inclusive, there is exactly one repeated number. Return this repeated number, without modifying the array and using only constant extra space.'),
('First Missing Positive', 'Given an unsorted integer array nums, return the smallest missing positive integer, using an algorithm that runs in O(n) time and uses O(1) auxiliary space.'),
('Merge Sorted Array', 'You are given two integer arrays nums1 and nums2, sorted in non-decreasing order, with nums1 having extra trailing space to hold the merged result. Merge nums2 into nums1 as one sorted array in place.'),
('Remove Duplicates from Sorted Array', 'Given an integer array nums sorted in non-decreasing order, remove the duplicates in place such that each unique element appears only once, and return the number of unique elements.'),
('Move Zeroes', 'Given an integer array nums, move all 0''s to the end of it while maintaining the relative order of the non-zero elements, doing this in place without making a copy of the array.'),
('Next Permutation', 'Given an array of integers nums, rearrange the numbers into the lexicographically next greater permutation of numbers; if no such arrangement exists, rearrange it as the lowest possible order, in place.'),
('Majority Element', 'Given an array nums of size n, return the majority element, defined as the element that appears more than n/2 times; you may assume the majority element always exists.'),
('Find Peak Element', 'A peak element is an element that is strictly greater than its neighbors. Given an integer array nums, find a peak element and return its index; the array may contain multiple peaks, and you may return any one.'),
('Search a 2D Matrix', 'Write an efficient algorithm that searches for a value target in an m x n matrix where each row is sorted in ascending order and the first integer of each row is greater than the last integer of the previous row.'),
('Median of Two Sorted Arrays', 'Given two sorted arrays nums1 and nums2 of size m and n respectively, return the median of the two sorted arrays, using an algorithm with O(log (m+n)) runtime complexity.'),
('Binary Search', 'Given an array of integers nums which is sorted in ascending order, and an integer target, write a function to search target in nums, returning its index if found, or -1 otherwise, in O(log n) time.'),
('Koko Eating Bananas', 'Koko loves to eat bananas, given piles of bananas and a number of hours h. Koko can decide her bananas-per-hour eating speed. Return the minimum integer eating speed such that she can eat all the bananas within h hours.'),
('Time Based Key-Value Store', 'Design a time-based key-value data structure that can store multiple values for the same key at different time stamps, and retrieve the key''s value at a certain timestamp, returning the value set at the largest timestamp smaller than or equal to the given one.'),
('Design Circular Queue', 'Design your implementation of a circular queue, a linear data structure that follows the FIFO principle and connects the last position back to the first to make a circle, supporting enqueue, dequeue, and boundary checks.'),
('LFU Cache', 'Design and implement a data structure for a Least Frequently Used (LFU) cache, supporting get and put operations, evicting the least frequently used key when the cache reaches capacity.'),
('All O`one Data Structure', 'Design a data structure that supports incrementing and decrementing the count of a key, as well as retrieving any key with the maximum count and any key with the minimum count, all in O(1) time.'),
('Random Pick with Weight', 'You are given an array of positive integers w where w[i] describes the weight of the ith index. Implement a function pickIndex that randomly picks an index in proportion to its weight.'),
('Insert Delete GetRandom O(1)', 'Implement a data structure that supports insert, remove, and getRandom operations in average O(1) time, where getRandom returns a random element from the current set of elements with equal probability.'),
('Shuffle an Array', 'Given an integer array nums, design an algorithm to randomly shuffle the array, ensuring every permutation is equally likely, and provide a reset method to return to the original configuration.'),
('Word Pattern', 'Given a pattern and a string s, find if s follows the same pattern, meaning there is a bijection between a letter in pattern and a non-empty word in s.'),
